#!/usr/bin/env python3
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
WORLD = ROOT / "rts/Rendering/WorldDrawer.cpp"


def replace_once(old: str, new: str) -> None:
    text = WORLD.read_text(encoding="utf-8")
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"Expected exactly one WorldDrawer anchor, found {count}")
    WORLD.write_text(text.replace(old, new, 1), encoding="utf-8", newline="\n")


# Keep the experiment self-contained in WorldDrawer so it is easy to throw away
# or merge later without adding new engine source files / CMake plumbing.
replace_once(
    '#include "System/LoadLock.h"\n\nCONFIG(bool, PreloadModels)',
    '''#include "System/LoadLock.h"\n\n#include <algorithm>\n#include <memory>\n\nCONFIG(bool, PreloadModels)'''
)

replace_once(
    'CONFIG(bool, PreloadModels).defaultValue(true).description("The engine will preload all models");\n',
    '''CONFIG(bool, PreloadModels).defaultValue(true).description("The engine will preload all models");\n\n// TEK2 isolated SSAO experiment. Defaults ON only because this branch is a\n// dedicated A/B-test build; stock Recoil behavior is restored with Tek2SSAO=0.\nCONFIG(bool, Tek2SSAO).defaultValue(true).headlessValue(false).description("TEK2 engine-level screen-space ambient occlusion");\nCONFIG(int, Tek2SSAOQuality).defaultValue(1).headlessValue(0).description("TEK2 SSAO quality: 0=8, 1=12, 2=16 samples");\nCONFIG(float, Tek2SSAORadius).defaultValue(4.0f).headlessValue(0.0f).description("TEK2 SSAO view-space radius");\nCONFIG(float, Tek2SSAOStrength).defaultValue(1.0f).headlessValue(0.0f).description("TEK2 SSAO darkness multiplier");\nCONFIG(bool, Tek2SSAODebug).defaultValue(false).headlessValue(false).description("Show TEK2 SSAO buffer instead of compositing it");\n\n#ifndef HEADLESS\nnamespace {\n\tGLuint tek2SSAOPrograms[3] = {0, 0, 0}; // AO, bilateral blur, composite\n\tGLuint tek2SSAODepthTex = 0;\n\tGLuint tek2SSAOTex[2] = {0, 0};\n\tstd::unique_ptr<FBO> tek2SSAODepthFBO;\n\tstd::unique_ptr<FBO> tek2SSAOFBO[2];\n\tint tek2SSAOViewX = 0;\n\tint tek2SSAOViewY = 0;\n\tint tek2SSAOHalfX = 0;\n\tint tek2SSAOHalfY = 0;\n\tbool tek2SSAOShaderFailed = false;\n\n\tstatic const char* TEK2_SSAO_VS = R"GLSL(\n#version 330 core\nout vec2 vUV;\nvoid main() {\n\tvec2 p = vec2(float((gl_VertexID << 1) & 2), float(gl_VertexID & 2));\n\tvUV = p * 0.5;\n\tgl_Position = vec4(p * 2.0 - 1.0, 0.0, 1.0);\n}\n)GLSL";\n\n\tstatic const char* TEK2_SSAO_FS = R"GLSL(\n#version 330 core\nin vec2 vUV;\nlayout(location = 0) out vec4 fragColor;\n\nuniform sampler2D depthTex;\nuniform mat4 invProjMatrix;\nuniform mat4 projMatrix;\nuniform int clipZeroOne;\nuniform int sampleCount;\nuniform float radius;\nuniform float strength;\n\nvec3 ReconstructViewPos(vec2 uv, float depth) {\n\tfloat z = (clipZeroOne != 0) ? depth : (depth * 2.0 - 1.0);\n\tvec4 p = invProjMatrix * vec4(uv * 2.0 - 1.0, z, 1.0);\n\treturn p.xyz / max(abs(p.w), 1e-7) * sign(p.w);\n}\n\nfloat Hash12(vec2 p) {\n\tvec3 p3 = fract(vec3(p.xyx) * 0.1031);\n\tp3 += dot(p3, p3.yzx + 33.33);\n\treturn fract((p3.x + p3.y) * p3.z);\n}\n\nvoid main() {\n\tfloat centerDepth = texture(depthTex, vUV).r;\n\tif (centerDepth >= 0.999999) {\n\t\tfragColor = vec4(1.0);\n\t\treturn;\n\t}\n\n\tvec3 centerPos = ReconstructViewPos(vUV, centerDepth);\n\tvec3 dx = dFdx(centerPos);\n\tvec3 dy = dFdy(centerPos);\n\tvec3 normal = normalize(cross(dx, dy));\n\tif (dot(normal, -centerPos) < 0.0)\n\t\tnormal = -normal;\n\n\tvec3 helper = (abs(normal.z) < 0.95) ? vec3(0.0, 0.0, 1.0) : vec3(0.0, 1.0, 0.0);\n\tvec3 tangent = normalize(cross(helper, normal));\n\tvec3 bitangent = cross(normal, tangent);\n\tmat3 tbn = mat3(tangent, bitangent, normal);\n\n\tfloat randAngle = Hash12(gl_FragCoord.xy) * 6.28318530718;\n\tfloat centerDist = length(centerPos);\n\tfloat occ = 0.0;\n\tfloat validSamples = 0.0;\n\tfloat safeRadius = max(radius, 0.05);\n\tfloat bias = max(0.035, safeRadius * 0.018);\n\n\tfor (int i = 0; i < 16; ++i) {\n\t\tif (i >= sampleCount) break;\n\n\t\tfloat fi = (float(i) + 0.5) / float(sampleCount);\n\t\tfloat phi = float(i) * 2.39996322973 + randAngle;\n\t\tfloat z = mix(0.18, 0.94, fi);\n\t\tfloat xy = sqrt(max(1.0 - z * z, 0.0));\n\t\tvec3 hemi = vec3(cos(phi) * xy, sin(phi) * xy, z);\n\t\tfloat sampleScale = mix(0.18, 1.0, fi * fi);\n\t\tvec3 samplePos = centerPos + (tbn * hemi) * (safeRadius * sampleScale);\n\n\t\tvec4 clip = projMatrix * vec4(samplePos, 1.0);\n\t\tif (abs(clip.w) < 1e-6) continue;\n\t\tvec2 suv = (clip.xy / clip.w) * 0.5 + 0.5;\n\t\tif (any(lessThan(suv, vec2(0.001))) || any(greaterThan(suv, vec2(0.999)))) continue;\n\n\t\tfloat sceneDepth = texture(depthTex, suv).r;\n\t\tif (sceneDepth >= 0.999999) continue;\n\n\t\tvec3 scenePos = ReconstructViewPos(suv, sceneDepth);\n\t\tfloat sceneDist = length(scenePos);\n\t\tfloat sampleDist = length(samplePos);\n\t\tfloat rangeWeight = 1.0 - smoothstep(0.0, safeRadius * 1.6, abs(sceneDist - centerDist));\n\t\tfloat blocked = (sceneDist + bias < sampleDist) ? 1.0 : 0.0;\n\t\tocc += blocked * rangeWeight;\n\t\tvalidSamples += 1.0;\n\t}\n\n\tfloat denom = max(validSamples, 1.0);\n\tfloat ao = clamp(1.0 - (occ / denom) * max(strength, 0.0), 0.0, 1.0);\n\t// Keep broad surfaces clean while retaining contact/cavity darkening.\n\tao = smoothstep(0.02, 1.0, ao);\n\tfragColor = vec4(ao, ao, ao, 1.0);\n}\n)GLSL";\n\n\tstatic const char* TEK2_SSAO_BLUR_FS = R"GLSL(\n#version 330 core\nin vec2 vUV;\nlayout(location = 0) out vec4 fragColor;\n\nuniform sampler2D aoTex;\nuniform sampler2D depthTex;\nuniform mat4 invProjMatrix;\nuniform int clipZeroOne;\nuniform vec2 direction;\nuniform float radius;\n\nvec3 ReconstructViewPos(vec2 uv, float depth) {\n\tfloat z = (clipZeroOne != 0) ? depth : (depth * 2.0 - 1.0);\n\tvec4 p = invProjMatrix * vec4(uv * 2.0 - 1.0, z, 1.0);\n\treturn p.xyz / max(abs(p.w), 1e-7) * sign(p.w);\n}\n\nvoid main() {\n\tvec2 texel = 1.0 / vec2(textureSize(aoTex, 0));\n\tfloat centerDepth = texture(depthTex, vUV).r;\n\tif (centerDepth >= 0.999999) { fragColor = vec4(1.0); return; }\n\tfloat centerDist = length(ReconstructViewPos(vUV, centerDepth));\n\tfloat sigma = 2.0;\n\tfloat depthSharpness = 7.0 / max(radius, 0.25);\n\tfloat sum = 0.0;\n\tfloat wsum = 0.0;\n\n\tfor (int i = -4; i <= 4; ++i) {\n\t\tfloat fi = float(i);\n\t\tvec2 uv = clamp(vUV + direction * texel * fi, vec2(0.0), vec2(1.0));\n\t\tfloat d = texture(depthTex, uv).r;\n\t\tfloat ao = texture(aoTex, uv).r;\n\t\tfloat spatialW = exp(-0.5 * (fi * fi) / (sigma * sigma));\n\t\tfloat depthW = 0.0;\n\t\tif (d < 0.999999) {\n\t\t\tfloat sampleDist = length(ReconstructViewPos(uv, d));\n\t\t\tdepthW = exp(-abs(sampleDist - centerDist) * depthSharpness);\n\t\t}\n\t\tfloat w = spatialW * depthW;\n\t\tsum += ao * w;\n\t\twsum += w;\n\t}\n\n\tfloat result = (wsum > 1e-5) ? (sum / wsum) : texture(aoTex, vUV).r;\n\tfragColor = vec4(result, result, result, 1.0);\n}\n)GLSL";\n\n\tstatic const char* TEK2_SSAO_COMPOSITE_FS = R"GLSL(\n#version 330 core\nin vec2 vUV;\nlayout(location = 0) out vec4 fragColor;\nuniform sampler2D aoTex;\nvoid main() {\n\tfloat ao = texture(aoTex, vUV).r;\n\tfragColor = vec4(ao, ao, ao, 1.0);\n}\n)GLSL";\n\n\tGLuint CompileTek2Shader(GLenum type, const char* source, const char* label) {\n\t\tGLuint shader = glCreateShader(type);\n\t\tglShaderSource(shader, 1, &source, nullptr);\n\t\tglCompileShader(shader);\n\t\tGLint ok = GL_FALSE;\n\t\tglGetShaderiv(shader, GL_COMPILE_STATUS, &ok);\n\t\tif (ok == GL_TRUE) return shader;\n\n\t\tchar logBuf[4096] = {};\n\t\tGLsizei logLen = 0;\n\t\tglGetShaderInfoLog(shader, sizeof(logBuf) - 1, &logLen, logBuf);\n\t\tLOG_L(L_ERROR, "[TEK2 SSAO] %s shader compile failed: %s", label, logBuf);\n\t\tglDeleteShader(shader);\n\t\treturn 0;\n\t}\n\n\tGLuint LinkTek2Program(const char* fragmentSource, const char* label) {\n\t\tGLuint vs = CompileTek2Shader(GL_VERTEX_SHADER, TEK2_SSAO_VS, label);\n\t\tGLuint fs = CompileTek2Shader(GL_FRAGMENT_SHADER, fragmentSource, label);\n\t\tif (vs == 0 || fs == 0) {\n\t\t\tif (vs != 0) glDeleteShader(vs);\n\t\t\tif (fs != 0) glDeleteShader(fs);\n\t\t\treturn 0;\n\t\t}\n\n\t\tGLuint program = glCreateProgram();\n\t\tglAttachShader(program, vs);\n\t\tglAttachShader(program, fs);\n\t\tglLinkProgram(program);\n\t\tglDeleteShader(vs);\n\t\tglDeleteShader(fs);\n\n\t\tGLint ok = GL_FALSE;\n\t\tglGetProgramiv(program, GL_LINK_STATUS, &ok);\n\t\tif (ok == GL_TRUE) return program;\n\n\t\tchar logBuf[4096] = {};\n\t\tGLsizei logLen = 0;\n\t\tglGetProgramInfoLog(program, sizeof(logBuf) - 1, &logLen, logBuf);\n\t\tLOG_L(L_ERROR, "[TEK2 SSAO] %s program link failed: %s", label, logBuf);\n\t\tglDeleteProgram(program);\n\t\treturn 0;\n\t}\n\n\tvoid DeleteTek2SSAOResources() {\n\t\ttek2SSAOFBO[0].reset();\n\t\ttek2SSAOFBO[1].reset();\n\t\ttek2SSAODepthFBO.reset();\n\n\t\tif (tek2SSAOTex[0] != 0) glDeleteTextures(2, tek2SSAOTex);\n\t\tif (tek2SSAODepthTex != 0) glDeleteTextures(1, &tek2SSAODepthTex);\n\t\ttek2SSAOTex[0] = tek2SSAOTex[1] = 0;\n\t\ttek2SSAODepthTex = 0;\n\t\ttek2SSAOViewX = tek2SSAOViewY = tek2SSAOHalfX = tek2SSAOHalfY = 0;\n\t}\n\n\tvoid KillTek2SSAO() {\n\t\tDeleteTek2SSAOResources();\n\t\tfor (GLuint& program: tek2SSAOPrograms) {\n\t\t\tif (program != 0) glDeleteProgram(program);\n\t\t\tprogram = 0;\n\t\t}\n\t\ttek2SSAOShaderFailed = false;\n\t}\n\n\tbool EnsureTek2SSAOPrograms() {\n\t\tif (tek2SSAOShaderFailed) return false;\n\t\tif (tek2SSAOPrograms[0] != 0 && tek2SSAOPrograms[1] != 0 && tek2SSAOPrograms[2] != 0) return true;\n\n\t\ttek2SSAOPrograms[0] = LinkTek2Program(TEK2_SSAO_FS, "AO");\n\t\ttek2SSAOPrograms[1] = LinkTek2Program(TEK2_SSAO_BLUR_FS, "bilateral blur");\n\t\ttek2SSAOPrograms[2] = LinkTek2Program(TEK2_SSAO_COMPOSITE_FS, "composite");\n\t\tif (tek2SSAOPrograms[0] == 0 || tek2SSAOPrograms[1] == 0 || tek2SSAOPrograms[2] == 0) {\n\t\t\ttek2SSAOShaderFailed = true;\n\t\t\treturn false;\n\t\t}\n\t\tLOG("[TEK2 SSAO] shaders initialized");\n\t\treturn true;\n\t}\n\n\tvoid SetupTek2Texture(GLuint tex, GLint internalFormat, GLenum format, GLenum type, int x, int y, bool linear) {\n\t\tglBindTexture(GL_TEXTURE_2D, tex);\n\t\tglTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, linear ? GL_LINEAR : GL_NEAREST);\n\t\tglTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, linear ? GL_LINEAR : GL_NEAREST);\n\t\tglTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE);\n\t\tglTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE);\n\t\tglTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_BASE_LEVEL, 0);\n\t\tglTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAX_LEVEL, 0);\n\t\tglTexImage2D(GL_TEXTURE_2D, 0, internalFormat, x, y, 0, format, type, nullptr);\n\t}\n\n\tbool CreateTek2SSAOResources() {\n\t\tDeleteTek2SSAOResources();\n\t\ttek2SSAOViewX = std::max(globalRendering->viewSizeX, 1);\n\t\ttek2SSAOViewY = std::max(globalRendering->viewSizeY, 1);\n\t\ttek2SSAOHalfX = std::max((tek2SSAOViewX + 1) / 2, 1);\n\t\ttek2SSAOHalfY = std::max((tek2SSAOViewY + 1) / 2, 1);\n\n\t\tglGenTextures(1, &tek2SSAODepthTex);\n\t\tconst GLint depthFormat = static_cast<GLint>(CGlobalRendering::DepthBitsToFormat(globalRendering->supportDepthBufferBitDepth));\n\t\tSetupTek2Texture(tek2SSAODepthTex, depthFormat, GL_DEPTH_COMPONENT, GL_FLOAT, tek2SSAOViewX, tek2SSAOViewY, false);\n\t\tglTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_COMPARE_MODE, GL_NONE);\n\n\t\ttek2SSAODepthFBO = std::make_unique<FBO>(true);\n\t\ttek2SSAODepthFBO->Init(false);\n\t\ttek2SSAODepthFBO->Bind();\n\t\ttek2SSAODepthFBO->AttachTexture(tek2SSAODepthTex, GL_TEXTURE_2D, GL_DEPTH_ATTACHMENT);\n\t\tglDrawBuffer(GL_NONE);\n\t\tconst bool depthOK = tek2SSAODepthFBO->CheckStatus("TEK2-SSAO-DEPTH");\n\t\tFBO::Unbind();\n\n\t\tglGenTextures(2, tek2SSAOTex);\n\t\tfor (int i = 0; i < 2; ++i) {\n\t\t\tSetupTek2Texture(tek2SSAOTex[i], GL_R8, GL_RED, GL_UNSIGNED_BYTE, tek2SSAOHalfX, tek2SSAOHalfY, true);\n\t\t\ttek2SSAOFBO[i] = std::make_unique<FBO>(true);\n\t\t\ttek2SSAOFBO[i]->Init(false);\n\t\t\ttek2SSAOFBO[i]->Bind();\n\t\t\ttek2SSAOFBO[i]->AttachTexture(tek2SSAOTex[i], GL_TEXTURE_2D, GL_COLOR_ATTACHMENT0);\n\t\t\tglDrawBuffer(GL_COLOR_ATTACHMENT0);\n\t\t\tif (!tek2SSAOFBO[i]->CheckStatus(i == 0 ? "TEK2-SSAO-AO" : "TEK2-SSAO-BLUR")) {\n\t\t\t\tFBO::Unbind();\n\t\t\t\tDeleteTek2SSAOResources();\n\t\t\t\treturn false;\n\t\t\t}\n\t\t\tFBO::Unbind();\n\t\t}\n\t\tglBindTexture(GL_TEXTURE_2D, 0);\n\n\t\tif (!depthOK) {\n\t\t\tDeleteTek2SSAOResources();\n\t\t\treturn false;\n\t\t}\n\n\t\tLOG("[TEK2 SSAO] buffers initialized at %dx%d (AO %dx%d)", tek2SSAOViewX, tek2SSAOViewY, tek2SSAOHalfX, tek2SSAOHalfY);\n\t\treturn true;\n\t}\n\n\tbool EnsureTek2SSAOResources() {\n\t\tif (tek2SSAOViewX == globalRendering->viewSizeX && tek2SSAOViewY == globalRendering->viewSizeY && tek2SSAODepthTex != 0 && tek2SSAOTex[0] != 0)\n\t\t\treturn true;\n\t\treturn CreateTek2SSAOResources();\n\t}\n\n\tvoid SetTek2Matrix(GLuint program, const char* name, const CMatrix44f& matrix) {\n\t\tconst GLint loc = glGetUniformLocation(program, name);\n\t\tif (loc >= 0) glUniformMatrix4fv(loc, 1, GL_FALSE, matrix);\n\t}\n\n\tvoid DrawTek2FullscreenTriangle() {\n\t\tglDrawArrays(GL_TRIANGLES, 0, 3);\n\t}\n\n\tvoid DrawTek2SSAO() {\n\t\tif (!configHandler->GetBool("Tek2SSAO")) return;\n\t\tif (!globalRendering->haveGL4) return;\n\t\tif (!EnsureTek2SSAOPrograms() || !EnsureTek2SSAOResources()) return;\n\n\t\tSCOPED_TIMER("Draw::World::TEK2SSAO");\n\t\tSCOPED_GL_DEBUGGROUP("Draw::World::TEK2SSAO");\n\n\t\tconst std::array<int, 4> srcRect = {\n\t\t\tglobalRendering->viewPosX, globalRendering->viewPosY,\n\t\t\tglobalRendering->viewPosX + tek2SSAOViewX, globalRendering->viewPosY + tek2SSAOViewY\n\t\t};\n\t\tconst std::array<int, 4> dstRect = {0, 0, tek2SSAOViewX, tek2SSAOViewY};\n\t\tif (!FBO::Blit(-1, tek2SSAODepthFBO->GetId(), srcRect, dstRect, GL_DEPTH_BUFFER_BIT, GL_NEAREST))\n\t\t\treturn;\n\n\t\tGLint oldViewport[4] = {};\n\t\tglGetIntegerv(GL_VIEWPORT, oldViewport);\n\t\tconst GLboolean oldDepthTest = glIsEnabled(GL_DEPTH_TEST);\n\t\tconst GLboolean oldBlend = glIsEnabled(GL_BLEND);\n\t\tconst GLboolean oldCull = glIsEnabled(GL_CULL_FACE);\n\t\tGLboolean oldDepthMask = GL_TRUE;\n\t\tglGetBooleanv(GL_DEPTH_WRITEMASK, &oldDepthMask);\n\n\t\tglDisable(GL_DEPTH_TEST);\n\t\tglDepthMask(GL_FALSE);\n\t\tglDisable(GL_BLEND);\n\t\tglDisable(GL_CULL_FACE);\n\n\t\tconst int quality = std::clamp(configHandler->GetInt("Tek2SSAOQuality"), 0, 2);\n\t\tconst int samples = (quality == 0) ? 8 : ((quality == 1) ? 12 : 16);\n\t\tconst float radius = std::max(configHandler->GetFloat("Tek2SSAORadius"), 0.05f);\n\t\tconst float strength = std::max(configHandler->GetFloat("Tek2SSAOStrength"), 0.0f);\n\t\tconst int clipZeroOne = globalRendering->supportClipSpaceControl ? 1 : 0;\n\n\t\t// 1) Half-resolution AO from the completed opaque depth buffer.\n\t\ttek2SSAOFBO[0]->Bind();\n\t\tglViewport(0, 0, tek2SSAOHalfX, tek2SSAOHalfY);\n\t\tglUseProgram(tek2SSAOPrograms[0]);\n\t\tglActiveTexture(GL_TEXTURE0); glBindTexture(GL_TEXTURE_2D, tek2SSAODepthTex);\n\t\tglUniform1i(glGetUniformLocation(tek2SSAOPrograms[0], "depthTex"), 0);\n\t\tglUniform1i(glGetUniformLocation(tek2SSAOPrograms[0], "clipZeroOne"), clipZeroOne);\n\t\tglUniform1i(glGetUniformLocation(tek2SSAOPrograms[0], "sampleCount"), samples);\n\t\tglUniform1f(glGetUniformLocation(tek2SSAOPrograms[0], "radius"), radius);\n\t\tglUniform1f(glGetUniformLocation(tek2SSAOPrograms[0], "strength"), strength);\n\t\tSetTek2Matrix(tek2SSAOPrograms[0], "invProjMatrix", camera->GetProjectionMatrixInverse());\n\t\tSetTek2Matrix(tek2SSAOPrograms[0], "projMatrix", camera->GetProjectionMatrix());\n\t\tDrawTek2FullscreenTriangle();\n\t\tFBO::Unbind();\n\n\t\t// 2) Two-pass depth-aware bilateral blur.\n\t\tglUseProgram(tek2SSAOPrograms[1]);\n\t\tglUniform1i(glGetUniformLocation(tek2SSAOPrograms[1], "aoTex"), 0);\n\t\tglUniform1i(glGetUniformLocation(tek2SSAOPrograms[1], "depthTex"), 1);\n\t\tglUniform1i(glGetUniformLocation(tek2SSAOPrograms[1], "clipZeroOne"), clipZeroOne);\n\t\tglUniform1f(glGetUniformLocation(tek2SSAOPrograms[1], "radius"), radius);\n\t\tSetTek2Matrix(tek2SSAOPrograms[1], "invProjMatrix", camera->GetProjectionMatrixInverse());\n\t\tglActiveTexture(GL_TEXTURE1); glBindTexture(GL_TEXTURE_2D, tek2SSAODepthTex);\n\n\t\ttek2SSAOFBO[1]->Bind();\n\t\tglActiveTexture(GL_TEXTURE0); glBindTexture(GL_TEXTURE_2D, tek2SSAOTex[0]);\n\t\tglUniform2f(glGetUniformLocation(tek2SSAOPrograms[1], "direction"), 1.0f, 0.0f);\n\t\tDrawTek2FullscreenTriangle();\n\t\tFBO::Unbind();\n\n\t\ttek2SSAOFBO[0]->Bind();\n\t\tglActiveTexture(GL_TEXTURE0); glBindTexture(GL_TEXTURE_2D, tek2SSAOTex[1]);\n\t\tglUniform2f(glGetUniformLocation(tek2SSAOPrograms[1], "direction"), 0.0f, 1.0f);\n\t\tDrawTek2FullscreenTriangle();\n\t\tFBO::Unbind();\n\n\t\t// 3) Multiply AO into the opaque world before alpha objects / particles.\n\t\tglViewport(globalRendering->viewPosX, globalRendering->viewPosY, tek2SSAOViewX, tek2SSAOViewY);\n\t\tglUseProgram(tek2SSAOPrograms[2]);\n\t\tglActiveTexture(GL_TEXTURE0); glBindTexture(GL_TEXTURE_2D, tek2SSAOTex[0]);\n\t\tglUniform1i(glGetUniformLocation(tek2SSAOPrograms[2], "aoTex"), 0);\n\n\t\tif (configHandler->GetBool("Tek2SSAODebug")) {\n\t\t\tglDisable(GL_BLEND);\n\t\t} else {\n\t\t\tglEnable(GL_BLEND);\n\t\t\tglBlendEquation(GL_FUNC_ADD);\n\t\t\tglBlendFunc(GL_ZERO, GL_SRC_COLOR);\n\t\t}\n\t\tDrawTek2FullscreenTriangle();\n\n\t\t// Restore the state expected by the regular world pipeline.\n\t\tglUseProgram(0);\n\t\tglActiveTexture(GL_TEXTURE1); glBindTexture(GL_TEXTURE_2D, 0);\n\t\tglActiveTexture(GL_TEXTURE0); glBindTexture(GL_TEXTURE_2D, 0);\n\t\tglViewport(oldViewport[0], oldViewport[1], oldViewport[2], oldViewport[3]);\n\t\tglDepthMask(oldDepthMask);\n\t\tif (oldDepthTest) glEnable(GL_DEPTH_TEST); else glDisable(GL_DEPTH_TEST);\n\t\tif (oldCull) glEnable(GL_CULL_FACE); else glDisable(GL_CULL_FACE);\n\t\tif (oldBlend) glEnable(GL_BLEND); else glDisable(GL_BLEND);\n\t\tglBlendEquation(GL_FUNC_ADD);\n\t\tglBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);\n\t}\n}\n#endif // !HEADLESS\n'''
)

replace_once(
    '''\tIGroundDecalDrawer::FreeInstance();\n\tDepthBufferCopy::Kill();\n\tLuaObjectDrawer::Kill();\n''',
    '''\tIGroundDecalDrawer::FreeInstance();\n#ifndef HEADLESS\n\tKillTek2SSAO();\n#endif\n\tDepthBufferCopy::Kill();\n\tLuaObjectDrawer::Kill();\n'''
)

replace_once(
    '''\tDrawOpaqueObjects();\n\tDrawAlphaObjects();\n''',
    '''\tDrawOpaqueObjects();\n#ifndef HEADLESS\n\tDrawTek2SSAO();\n#endif\n\tDrawAlphaObjects();\n'''
)

print("Patched rts/Rendering/WorldDrawer.cpp with isolated TEK2 SSAO")
